// Private phone-bound booking credentials are generated by the authenticated owner only.
const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
export const normalizeBookingCode = code => typeof code === 'string' && code.length <= 40 ? code.toUpperCase().replace(/[\s-]/g, '') : '';
export const validBookingCode = code => /^[A-HJ-NP-Z2-9]{16}$/.test(normalizeBookingCode(code));
export function generateBookingCode(random = globalThis.crypto) {
  const value = Array.from(random.getRandomValues(new Uint8Array(16)), byte => alphabet[byte & 31]).join('');
  return value.match(/.{4}/g).join('-');
}
